 this.root.innerHTML=`<div class="run-pages" aria-label="Environment pages">${this.document.pages.map((p,i)=>button(p.name,'page',`data-index="${i}" aria-pressed="${i===this.pageIndex}"`)).join('')}</div><div class="run-blocks">${this.page.blocks.map((block,j)=>`<section class="run-block ${block.width==='half'?'half':''} ${j===this.blockIndex?'controlled':''}"><div class="run-block-head"><h3>${esc(block.name)}</h3>${this.page.blocks.length>1?button(j===this.blockIndex?'Active control':'Control this block','focus',`data-index="${j}" aria-pressed="${j===this.blockIndex}"`):''}</div><div class="run-board ${block.layout}" data-board="${j}" style="--rows:${block.rows};--cols:${block.columns}">${block.scene?.selection.mode==='target'?`<span class="run-selection-target" style="left:${block.scene.selection.x*100}%;top:${block.scene.selection.y*100}%;width:${block.scene.selection.radius*200}%;height:${block.scene.selection.radius*200}%" aria-label="Selection target"></span>`:''}${block.layout==='ring'?'<span class="dial-marker" aria-hidden="true">▼</span>':''}${block.layout==='sketch'?'<span class="draw-placeholder">Draw a symbol here</span>':itemPositions(block).map(p=>`<button class="run-cell ${p.item.kind==='label'?'display-label':''}" ${p.item.kind==='label'?'disabled':''} data-run="item" data-block="${j}" data-index="${p.i}" style="--x:${p.x*100}%;--y:${p.y*100}%;--w:${p.w*100}%;--h:${p.h*100}%" aria-label="${block.input.source==='finger-pair'?`Row ${Math.floor(p.i/block.columns)}, column ${p.i%block.columns}: `:''}${esc(p.item.label)}">${esc(p.item.label)}</button>`).join('')}<canvas class="run-ink" width="700" height="700" aria-label="Drawing input" tabindex="${['trace','swipe','recognize'].includes(block.input.behavior)?0:-1}"></canvas><span class="run-cursor" hidden></span></div></section>`).join('')}</div>${b?`<p class="run-instructions">${esc(this.instructions())}</p><div class="run-progress"><progress max="1" value="0" aria-label="Hold to select"></progress><span class="run-target"></span></div><p class="run-status" role="status"></p><div class="run-candidates" aria-label="Review recognition"></div><div class="button-row run-tools">${b.input.source==='scan'?button('Next','next')+button('Select','select')+button('Back to rows','back'):''}${b.scene?.bindings.length?button('Center inputs','center'):''}${b.input.source==='rotation'?button('Center hand rotation','center'):''}${['pen','pointer-hand'].includes(b.input.source)?button('Center on my finger','center'):''}${['trace','swipe','recognize'].includes(b.input.behavior)?button('Review drawing','review')+button('Clear drawing','clear')+button('Save example','example','hidden'):''}${button('Space','space')+button('Delete','delete')+button('Undo','undo')}</div><details class="run-help"><summary>Input details</summary><p>${esc(SOURCES[b.input.source])} · ${esc(MODELS[b.input.model].name)}</p><p>${esc(MODELS[b.input.model].detail)}</p><p>Only the active block receives camera input. Mouse and touch remain available.</p></details>`:'<p>Add a block to preview your environment.</p>'}`;
 this.root.onclick=e=>{const el=e.target.closest('[data-run]');if(!el)return;e.preventDefault();const command=el.dataset.run,index=Number(el.dataset.index);if(command==='page')this.setPage(index);else if(command==='focus')this.setBlock(index);else if(command==='item'){if(Number(el.dataset.block)!==this.blockIndex)this.setBlock(Number(el.dataset.block));const item=this.block?.items[index];if(this.block?.input.behavior==='trace'&&item?.action==='text'){this.word+=item.value;this.feedback();}else if(item)this.emit(item);}else if(command==='candidate')this.accept(index);else if(command==='next'||command==='select')this.gesture(command);else if(command==='back'){this.scanLevel='row';this.col=0;this.paint();}else if(command==='center'){if(this.sceneControl){this.sceneControl.center();this.setStatus('Inputs centered. Make a fresh movement.');}else if(this.block.input.source==='rotation'){this.rotation.center();this.turn=0;}else this.center=this.rawPoint?{...this.rawPoint}:null;this.hold.reset();this.setStatus('Centered. Move to a choice, then hold.');this.paint();}else if(command==='review')this.recognize();else if(command==='clear')this.clearInk();else if(command==='example')this.options.onSketch?.(compactSketch(this.strokes));else this.emit({action:command,value:'',label:command});};
