 if(this.sceneControl&&!['trace','swipe'].includes(x.behavior)){const out=this.sceneControl.update(frame);if(out){this.scenePositions=out.positions;this.highlight=out.highlight;this.cursor=b.scene.selection.mode==='cursor'?out.cursor:null;this.hold.progress=out.progress;this.setStatus(b.scene.selection.mode==='pointer'?'Select a choice with a mouse, touch, or keyboard.':b.scene.selection.mode==='scan'?'Use Next and Select to choose.':out.status);if(out.fire!==null)this.emit(b.items[out.fire]);this.paint();}return;}
 if(x.source==='scan'||x.source==='pointer')return;if(Number.isFinite(at)&&at===this.lastHandAt&&frame.now-at<=200)return;this.lastHandAt=at;
