 if(x.source==='finger-pair'){const pair=this.fingers.update(frame,x.swap);if(pair&&!pair.missing&&!pair.settling&&pair.row!==null&&pair.col!==null){if(x.activation==='neutral'&&pair.row===0&&pair.col===0){this.neutralAt??=at;if(at-this.neutralAt>200){this.neutral=true;this.hold.reset();}this.setStatus('Armed. Choose a hand code.');}else{this.neutralAt=null;if((x.activation!=='neutral'||this.neutral)&&pair.row<b.rows&&pair.col<b.columns)index=pair.row*b.columns+pair.col;this.setStatus(`Row ${pair.row} · column ${pair.col}${x.activation==='neutral'&&!this.neutral?' · close both fists to arm':''}`);}}else{this.neutralAt=null;this.setStatus('Show both hands clearly, with palms toward the camera.');}}
 if(x.source==='finger-count'){const hands=(frame.hands||[]).map((p,i)=>({p,w:frame.handWorld?.[i]})).sort((a,b)=>x.hand==='right'?a.p[0].x-b.p[0].x:b.p[0].x-a.p[0].x);const h=hands[0];index=h?countFingers(h.p,h.w,frame.handAspect):null;this.setStatus(index===null?'Show a clear hand count.':`${index} fingers`);}
 if(x.source==='pointer-hand'||x.source==='pen'){const pen=this.pen.update(frame);if(pen?.point){this.rawPoint=pen.point;this.center??={...pen.point};const map=p=>({x:.5+(p.x-this.center.x)*x.gain,y:.5+(p.y-this.center.y)*x.gain});this.cursor=map(pen.point);if(x.source==='pointer-hand'||x.behavior==='select'&&pen.down)index=hitItem(b,this.cursor,itemPositions(b));else if(!this.pointer&&!this.working&&!this.candidates.length){if(pen.down){for(const sample of pen.samples||[])this.addPoint(map(sample.point),true);if(!(pen.samples||[]).length)this.addPoint(this.cursor,true);}if(pen.released)this.endStroke();if(pen.interrupted){this.stroke=null;this.pendingAt=0;this.setStatus('Tracking interrupted. Review or clear the drawing.');}}if(this.candidates.length){const accepted=this.acceptGate.update(pen.thumbUp?'yes':null,at,frame.now);if(accepted)this.accept(this.candidateIndex||0);}}else{this.cursor=null;if(pen?.interrupted){this.stroke=null;this.pendingAt=0;this.setStatus('Tracking interrupted. Review or clear the drawing.');}}}
