 words(data){if(!this.wordWorker){this.wordWorker=new Worker(new URL('./creator-word-worker.js',import.meta.url),{type:'module'});this.wordWorker.onmessage=({data})=>{const job=this.jobs.get(data.id);if(!job)return;clearTimeout(job.timer);this.jobs.delete(data.id);data.error?job.reject(new Error(data.error)):job.resolve(data);};this.wordWorker.onerror=()=>this.stopWords('Could not load the local word decoder.');}return new Promise((resolve,reject)=>{const id=++this.serial,timer=setTimeout(()=>{this.jobs.delete(id);reject(new Error('Word decoder timed out. Try again.'));},30000);this.jobs.set(id,{resolve,reject,timer});this.wordWorker.postMessage({...data,id});});}
